    scope = scope.new_child({
        Path: [],
        T: target,
        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope.maps[0],
        CHILD_ERRORS: [],
        NO_PYFRAME: True,
        MODE: AUTO,
        MIN_MODE: None,
    })
    scope.maps[0][LAST_CHILD_SCOPE] = scope.maps[0]

    try:
        ret = _glom(target, spec, scope)
    except skip_exc as e:
        if default is _MISSING:
            raise
        ret = default
    except GlomError as e:
        if not glom_debug:
            e._finalize(scope)
            raise
        raise
    except Exception as e:
        if isinstance(e, skip_exc):
            if default is _MISSING:
                raise
